BEGIN TRANSACTION;
CREATE TABLE android_metadata (locale TEXT);
CREATE TABLE "graph_preferences" ("name" TEXT NOT NULL, "metric" TEXT NOT NULL DEFAULT 'bestWeight', "period" TEXT NOT NULL DEFAULT 'day', "limit" INTEGER NOT NULL DEFAULT 20, "time_based_x_axis" INTEGER NOT NULL DEFAULT 0 CHECK ("time_based_x_axis" IN (0, 1)), "notes" TEXT NULL, PRIMARY KEY ("name"));
CREATE TABLE "gym_sets" ("body_weight" REAL NOT NULL DEFAULT 0.0, "cardio" INTEGER NOT NULL DEFAULT 0 CHECK ("cardio" IN (0, 1)), "category" TEXT NULL, "created" INTEGER NOT NULL, "distance" REAL NOT NULL DEFAULT 0.0, "duration" REAL NOT NULL DEFAULT 0.0, "hidden" INTEGER NOT NULL DEFAULT 0 CHECK ("hidden" IN (0, 1)), "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "image" TEXT NULL, "incline" INTEGER NULL, "name" TEXT NOT NULL, "notes" TEXT NULL, "plan_id" INTEGER NULL, "reps" REAL NOT NULL, "rest_ms" INTEGER NULL, "unit" TEXT NOT NULL, "weight" REAL NOT NULL);
CREATE TABLE "metadata" ("build_number" INTEGER NOT NULL);
CREATE TABLE "nutrition_expenditures" ("local_date" TEXT NOT NULL, "calories" REAL NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("local_date"));
CREATE TABLE "nutrition_foods" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "local_date" TEXT NOT NULL, "calories" REAL NOT NULL, "grams" REAL NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "plan_exercises" ("enabled" INTEGER NOT NULL CHECK ("enabled" IN (0, 1)), "timers" INTEGER NOT NULL DEFAULT 1 CHECK ("timers" IN (0, 1)), "exercise" TEXT NOT NULL REFERENCES gym_sets (name), "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "max_sets" INTEGER NULL, "plan_id" INTEGER NOT NULL REFERENCES plans (id), "warmup_sets" INTEGER NULL, "sequence" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "plans" ("days" TEXT NOT NULL, "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "sequence" INTEGER NULL, "title" TEXT NULL);
CREATE TABLE "settings" ("alarm_sound" TEXT NOT NULL, "automatic_backups" INTEGER NOT NULL DEFAULT 0 CHECK ("automatic_backups" IN (0, 1)), "backup_path" TEXT NULL, "cardio_unit" TEXT NOT NULL, "curve_lines" INTEGER NOT NULL CHECK ("curve_lines" IN (0, 1)), "curve_smoothness" REAL NULL, "duration_estimation" INTEGER NOT NULL DEFAULT 1 CHECK ("duration_estimation" IN (0, 1)), "enable_sound" INTEGER NOT NULL DEFAULT 1 CHECK ("enable_sound" IN (0, 1)), "explained_permissions" INTEGER NOT NULL CHECK ("explained_permissions" IN (0, 1)), "group_history" INTEGER NOT NULL CHECK ("group_history" IN (0, 1)), "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "long_date_format" TEXT NOT NULL, "max_sets" INTEGER NOT NULL, "notifications" INTEGER NOT NULL DEFAULT 1 CHECK ("notifications" IN (0, 1)), "notification_permission_requested" INTEGER NOT NULL DEFAULT 0 CHECK ("notification_permission_requested" IN (0, 1)), "peek_graph" INTEGER NOT NULL DEFAULT 0 CHECK ("peek_graph" IN (0, 1)), "plan_trailing" TEXT NOT NULL, "rep_estimation" INTEGER NOT NULL DEFAULT 0 CHECK ("rep_estimation" IN (0, 1)), "rest_timers" INTEGER NOT NULL CHECK ("rest_timers" IN (0, 1)), "short_date_format" TEXT NOT NULL, "show_body_weight" INTEGER NOT NULL DEFAULT 1 CHECK ("show_body_weight" IN (0, 1)), "show_categories" INTEGER NOT NULL DEFAULT 1 CHECK ("show_categories" IN (0, 1)), "show_images" INTEGER NOT NULL DEFAULT 1 CHECK ("show_images" IN (0, 1)), "show_notes" INTEGER NOT NULL DEFAULT 1 CHECK ("show_notes" IN (0, 1)), "show_global_progress" INTEGER NOT NULL DEFAULT 1 CHECK ("show_global_progress" IN (0, 1)), "show_units" INTEGER NOT NULL CHECK ("show_units" IN (0, 1)), "strength_unit" TEXT NOT NULL, "system_colors" INTEGER NOT NULL CHECK ("system_colors" IN (0, 1)), "tabs" TEXT NOT NULL DEFAULT 'HistoryPage,PlansPage,GraphsPage,TimerPage', "theme_mode" TEXT NOT NULL, "timer_duration" INTEGER NOT NULL, "vibrate" INTEGER NOT NULL CHECK ("vibrate" IN (0, 1)), "warmup_sets" INTEGER NULL, "scrollable_tabs" INTEGER NOT NULL DEFAULT 1 CHECK ("scrollable_tabs" IN (0, 1)), "show_graph_x_axis" INTEGER NOT NULL DEFAULT 0 CHECK ("show_graph_x_axis" IN (0, 1)), "show_graph_limit" INTEGER NOT NULL DEFAULT 1 CHECK ("show_graph_limit" IN (0, 1)), "progress_position" TEXT NOT NULL DEFAULT 'bottom', "default_graph_metric" TEXT NOT NULL DEFAULT 'bestWeight', "default_graph_period" TEXT NOT NULL DEFAULT 'day', "default_graph_limit" INTEGER NOT NULL DEFAULT 20, "default_graph_time_based_x_axis" INTEGER NOT NULL DEFAULT 0 CHECK ("default_graph_time_based_x_axis" IN (0, 1)), "keep_screen_on" INTEGER NOT NULL DEFAULT 0 CHECK ("keep_screen_on" IN (0, 1)), "input_style" TEXT NOT NULL DEFAULT 'underline');
CREATE TABLE "training_date_plans" ("id" TEXT NOT NULL, "template_id" TEXT NOT NULL, "name" TEXT NOT NULL, "exercises" TEXT NOT NULL, "local_date" TEXT NOT NULL, "status" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "training_sessions" ("id" TEXT NOT NULL, "plan_id" TEXT NOT NULL UNIQUE, "active_slot" INTEGER NULL UNIQUE, "local_date" TEXT NOT NULL, "state" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "training_set_results" ("id" TEXT NOT NULL, "session_id" TEXT NOT NULL, "exercise_id" TEXT NOT NULL, "exercise_index" INTEGER NOT NULL, "set_index" INTEGER NOT NULL, "measurements" TEXT NOT NULL, "gym_set_id" INTEGER NOT NULL UNIQUE, "local_date" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("session_id", "exercise_index", "set_index"));
CREATE TABLE "training_templates" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "exercises" TEXT NOT NULL, "local_date" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX gym_sets_name_hidden_created ON gym_sets(name, hidden, created);
CREATE INDEX gym_sets_created ON gym_sets(created);
CREATE INDEX gym_sets_plan_id ON gym_sets(plan_id);
CREATE INDEX plan_exercises_plan_id ON plan_exercises(plan_id);
DELETE FROM "sqlite_sequence";
COMMIT;
PRAGMA user_version=58;
